INSERT INTO landing_sections (section_key, title, subtitle, body_text, cta_primary_text, cta_primary_link, cta_secondary_text, cta_secondary_link, position) VALUES
('hero', 'Your AI-Powered WhatsApp CRM', 'Shared inbox, smart automations, broadcast campaigns, and AI replies — all in one platform. Built for teams that sell on WhatsApp.', NULL, 'Start Free Trial', '/signup', 'Watch Demo', '#demo', 1),
('social_proof', 'Trusted by 500+ businesses worldwide', NULL, NULL, NULL, NULL, NULL, NULL, 2),
('features', 'Everything you need to sell on WhatsApp', 'Replai brings together the tools your team needs to manage customer conversations at scale.', NULL, NULL, NULL, NULL, NULL, 3),
('how_it_works', 'Get started in 3 simple steps', 'From setup to your first AI-powered reply in under 10 minutes.', NULL, NULL, NULL, NULL, NULL, 4),
('ai_highlight', 'AI That Actually Understands Your Business', 'Upload your docs, FAQs, and product info. Replai builds a knowledge base and uses hybrid retrieval (full-text + vector search) to give accurate, context-aware replies — not generic chatbot fluff.', NULL, 'Learn More', '#features', NULL, NULL, 5),
('integrations', 'Plays well with your stack', 'Built on open standards. Connect to the tools you already use.', NULL, NULL, NULL, NULL, NULL, 6),
('pricing', 'Simple, transparent pricing', 'Start free. Scale as you grow. No per-seat AI fees.', NULL, NULL, NULL, NULL, NULL, 7),
('testimonials', 'Loved by teams worldwide', 'See what our customers have to say about Replai.', NULL, NULL, NULL, NULL, NULL, 8),
('cta_banner', 'Ready to transform your WhatsApp sales?', 'Join 500+ businesses using Replai to engage customers, close deals, and automate conversations.', NULL, 'Get Started Free', '/signup', NULL, NULL, 9)
INSERT INTO landing_features (icon_name, title, description, position) VALUES
('MessageSquare', 'Shared Team Inbox', 'Multiple agents, one WhatsApp number. Assign conversations, track status, add internal notes. Never miss a customer message.', 1),
('Bot', 'AI Reply Assistant', 'AI-drafted replies powered by OpenAI, Anthropic, or Gemini. Add a knowledge base (FAQs, docs) and the AI answers from your own content.', 2),
('Workflow', 'Visual Automations', 'No-code automation builder with triggers, conditions, delays, webhooks, and tag management. Build complex workflows visually.', 3),
('Send', 'Broadcast Campaigns', 'Send Meta-approved template messages to thousands. Track delivery, read, and reply rates in real-time.', 4),
('Kanban', 'Sales Pipelines', 'Kanban deal boards linked to conversations. Track deal value, stages, and expected close dates.', 5),
('Users', 'Contact Management', 'Tags, custom fields, CSV import, phone deduplication, and full conversation history per contact.', 6)
