('Enterprise', 'Custom', 'Custom', 'contact us', '["Unlimited contacts", "Unlimited team members", "All automations & flows", "Unlimited messages", "Multi-provider AI (OpenAI, Anthropic, Gemini)", "Dedicated account manager", "SLA guarantee", "Custom integrations", "MCP server access"]', FALSE, 'Contact Sales', 3)
INSERT INTO landing_testimonials (quote, author_name, author_role, author_company, rating, position) VALUES
('Replai transformed how we handle customer support. AI replies save our team 4 hours every day, and the shared inbox means nothing falls through the cracks.', 'Sarah Chen', 'Head of Customer Success', 'TechStart Solutions', 5, 1),
('We switched from 3 separate tools to just Replai. The automation builder alone paid for itself in the first week.', 'Marcus Johnson', 'CEO', 'GreenLeaf Commerce', 5, 2),
('The knowledge base feature is incredible. Our AI assistant actually answers questions accurately because it reads from our own product docs.', 'Priya Patel', 'Operations Manager', 'FastTrack Logistics', 5, 3)
