INSERT INTO legal_pages (slug, title, content_markdown) VALUES
('privacy-policy', 'Privacy Policy', '# Privacy Policy\n\n**Last updated: July 29, 2026**\n\n## 1. Introduction\n\nReplai (operated by Junkies Coder) respects your privacy. This policy explains how we collect, use, and protect your data when you use our WhatsApp CRM platform.\n\n## 2. Information We Collect\n\n### Account Information\n- Name and email address provided during registration\n- Password (stored hashed, never in plaintext)\n- Profile avatar (optional)\n\n### WhatsApp Business API Data\n- Messages sent and received through the platform\n- Contact information (phone numbers, names)\n- Conversation metadata (timestamps, status)\n- Template message content and delivery status\n\n### Usage Analytics\n- Feature usage patterns\n- Login timestamps and session duration\n- Browser and device information\n\n## 3. How We Use Your Information\n\n- Providing CRM services (inbox, contacts, pipelines, broadcasts)\n- Processing WhatsApp messages on your behalf\n- AI-powered features (reply generation, knowledge base queries)\n- Platform analytics and improvement\n- Security monitoring and fraud prevention\n\n## 4. Data Storage & Security\n\n- AES-256-GCM encryption for API tokens at rest\n- Supabase PostgreSQL with Row-Level Security (RLS)\n- HMAC-SHA256 webhook signature verification\n- TLS 1.3 encryption for all data in transit\n- Rate limiting on all API endpoints\n\n## 5. Third-Party Services\n\n- **Meta** — WhatsApp Business API (message delivery)\n- **Supabase** — Database hosting and authentication\n- **AI Providers** — OpenAI, Anthropic, Google (only when configured by you using your own API keys)\n\n## 6. Data Retention\n\nMessage history and account data are retained while your account is active. Upon account deletion, all associated data is permanently removed within 30 days.\n\n## 7. Your Rights\n\n- **Access** — Request a copy of your personal data\n- **Correction** — Update inaccurate information\n- **Deletion** — Request account and data deletion\n- **Data Portability** — Export your data in standard formats\n- **Opt-out** — Disable AI processing for your conversations\n\n## 8. WhatsApp Business API Compliance\n\nWe comply with Meta''s Business Messaging policies and WhatsApp Business Terms of Service. All template messages require Meta approval before sending.\n\n## 9. Children''s Privacy\n\nReplai is not intended for users under 18 years of age.\n\n## 10. Changes to This Policy\n\nWe may update this policy periodically. Users will be notified via email of significant changes.\n\n## 11. Contact Us\n\nFor privacy inquiries: privacy@junkiescoder.com'),
('terms-of-service', 'Terms of Service', '# Terms of Service\n\n**Effective Date: July 29, 2026**\n\n## 1. Acceptance of Terms\n\nBy using Replai, you agree to these Terms of Service.\n\n## 2. Description of Service\n\nReplai provides a self-hosted WhatsApp CRM platform with shared inbox, AI replies, automations, broadcasts, sales pipelines, and contact management.\n\n## 3. Account Registration & Security\n\nYou must provide accurate information during registration, maintain password security, and are responsible for all activity under your account.\n\n## 4. Acceptable Use\n\nYou must not send spam, violate WhatsApp policies, use the service for illegal purposes, or attempt to reverse-engineer the platform.\n\n## 5. WhatsApp Business API Compliance\n\nYou must comply with Meta''s Commerce Policy, Business Messaging guidelines, and maintain a valid WhatsApp Business Account.\n\n## 6. AI Features Disclaimer\n\nAI-generated replies are suggestions only. You are responsible for reviewing all AI outputs before sending to customers. Replai is not liable for AI-generated content.\n\n## 7. Data Ownership\n\nYou retain full ownership of your data (contacts, messages, templates). Replai does not sell or share user data with third parties.\n\n## 8. Service Availability\n\nWe provide best-effort uptime with no guaranteed SLA for self-hosted deployments.\n\n## 9. Intellectual Property\n\nReplai branding, documentation, and code are property of Junkies Coder (MIT licensed).\n\n## 10. Limitation of Liability\n\nReplai is provided "as is" without warranty. We are not liable for indirect, incidental, or consequential damages.\n\n## 11. Termination\n\nEither party may terminate. User data will be deleted within 30 days of account closure.\n\n## 12. Governing Law\n\nThese terms are governed by applicable local laws.\n\n## 13. Contact\n\nFor legal inquiries: legal@junkiescoder.com'),
('data-processing-agreement', 'Data Processing Agreement', '# Data Processing Agreement\n\n**Effective Date: July 29, 2026**\n\n## 1. Definitions\n\n- **Data Controller**: The customer using Replai\n- **Data Processor**: Replai (Junkies Coder)\n- **Personal Data**: Any data relating to identified individuals\n- **Processing**: Any operation performed on personal data\n\n## 2. Scope & Purpose\n\nThis DPA governs how Replai processes personal data on behalf of the customer as part of providing WhatsApp CRM services.\n\n## 3. Data Processing Details\n\n**Types of data processed:**\n- WhatsApp messages and conversation metadata\n- Contact information (phone numbers, names, emails)\n- AI interaction logs (when AI features are enabled)\n- User account and authentication data\n\n## 4. Security Measures\n\n- AES-256-GCM encryption at rest for sensitive tokens\n- TLS 1.3 encryption in transit\n- Row-Level Security (RLS) database isolation per account\n- HMAC-SHA256 webhook verification\n- Rate limiting on all endpoints\n\n## 5. Sub-processors\n\n- **Supabase** — Database hosting and authentication\n- **Meta** — WhatsApp Business API\n- **AI Providers** — Only when configured by customer using their own keys\n\n## 6. Data Retention & Deletion\n\nData is retained during active subscription and deleted within 30 days of account termination.\n\n## 7. Contact\n\nFor DPA inquiries: dpa@junkiescoder.com'),
('cookie-policy', 'Cookie Policy', '# Cookie Policy\n\n**Last updated: July 29, 2026**\n\n## 1. What Are Cookies\n\nCookies are small text files stored on your device when you visit our platform.\n\n## 2. How We Use Cookies\n\n- **Essential cookies** — Authentication and session management\n- **Functional cookies** — User preferences and theme settings\n- **Analytics cookies** — Usage tracking for platform improvement\n\n## 3. Types of Cookies We Use\n\n| Cookie Name | Purpose | Duration | Type |\n|---|---|---|---|\n| sb-auth-token | Supabase authentication session | Session | Essential |\n| theme | User theme preference | 1 year | Functional |\n| locale | User language preference | 1 year | Functional |\n\n## 4. Third-Party Cookies\n\nWe do not use third-party advertising cookies. Supabase may set cookies for authentication.\n\n## 5. Managing Cookies\n\nYou can manage cookies through your browser settings. Disabling essential cookies may affect platform functionality.\n\n## 6. Contact\n\nFor cookie inquiries: privacy@junkiescoder.com'),
('acceptable-use-policy', 'Acceptable Use Policy', '# Acceptable Use Policy\n\n**Effective Date: July 29, 2026**\n\n## 1. Purpose\n\nThis policy defines acceptable behavior when using Replai to send WhatsApp messages.\n\n## 2. Prohibited Activities\n\n- Sending unsolicited bulk messages (spam)\n- Sending messages without proper opt-in consent\n- Distributing malware, phishing links, or harmful content\n- Impersonating other businesses or individuals\n- Violating Meta''s WhatsApp Business Policy\n- Using AI features to generate misleading or illegal content\n- Attempting to circumvent rate limits or security measures\n- Harvesting contact data without consent\n\n## 3. WhatsApp Compliance\n\nYou must follow Meta''s 24-hour messaging window rules, use approved templates for outbound messages, and maintain acceptable quality ratings.\n\n## 4. AI Usage Guidelines\n\n- Review all AI replies before sending to customers\n- Do not rely solely on AI for sensitive communications\n- Keep knowledge base content accurate and current\n\n## 5. Enforcement\n\nViolations may result in account suspension or permanent ban.\n\n## 6. Contact\n\nReport violations: abuse@junkiescoder.com')
